#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
public:
    Cat(string n) : name(n) {
        cout << "先搭基类那一半：" << name << endl;
    }
    ~Cat() {
        cout << "后拆基类那一半：" << name << endl;
    }
};

class Kitten : public Cat {
public:
    Kitten(string n) : Cat(n) {
        cout << "再初始化子类成员：" << name << endl;
    }
    ~Kitten() {
        cout << "先执行子类的清理：" << name << endl;
    }
};

int main() {
    string name;
    cin >> name;

    Kitten k(name);
